/* ================== DOULA ================== */
function cName(c){return (c.nom||'').replace(/^Exemple – /,'')}
function cFirst(c){return cName(c).split(' ')[0]||''}
function cStage(c){const nb=parseD(c.naiss);if(nb)return {k:'pp',day:diffD(new Date(),nb)};const d=parseD(c.dpa);if(!d)return {k:'none'};const [w,dd]=gaAt(d,new Date());return {k:'preg',w,d:dd,left:diffD(d,new Date())}}
function cPaid(c){return (c.paie||[]).reduce((s,p)=>s+(+p.montant||0),0)}
function cPrice(c){return (FORFAITS[c.forfait]||{}).prix||0}
function enGarde(c){const s=cStage(c);return s.k==='preg'&&s.w>=38&&s.w<42}
function overlaps(){const L=S.clients.filter(c=>cStage(c).k==='preg');const out=[];for(let i=0;i<L.length;i++)for(let j=i+1;j<L.length;j++){const g=Math.abs(diffD(parseD(L[i].dpa),parseD(L[j].dpa)));if(g<14)out.push([L[i],L[j],g])}return out}
function stageTag(c){const s=cStage(c);return s.k==='pp'?'<span class="pill sage">Post-partum · jour '+s.day+'</span>':s.k==='preg'?(s.w>=38?'<span class="pill gold">En garde · '+s.w+' + '+s.d+'</span>':'<span class="pill acc">'+s.w+' SA + '+s.d+'</span>'):'<span class="pill line">Date à compléter</span>'}
function fillMsg(t,c){const D=S.doula;return t.replace(/\[prénom du bébé\]/g,(c&&c.bebe)||'[prénom du bébé]').replace(/\[prénoms?\]/g,c?cFirst(c):'[prénom]').replace(/\[ma signature\]/g,D.nom).replace(/\[nom, numéro\]/g,(D.rempNom||'[nom]')+', '+(D.rempTel||'[numéro]')).replace(/\[Nom\]/g,D.rempNom||'[Nom]').replace(/\[numéro\]/g,D.rempTel||'[numéro]')}
function lettreEquipe(c){const D=S.doula;return 'Bonjour,\n\nJe m\'appelle '+D.nom+'. Je suis la doula de '+(c?cName(c)+(c.partenaire?' et '+c.partenaire:''):'____________')+' et je les accompagne depuis leur grossesse.\n\nMon rôle est d\'offrir un soutien émotionnel, physique et informationnel non médical : mesures de confort, positions, respiration, présence continue. Je soutiens aussi le partenaire.\n\nCe que je ne fais pas\n- Je ne pose aucun geste médical et je n\'interprète aucun résultat.\n- Je ne prends aucune décision et je ne parle pas à la place des parents.\n- Je ne m\'oppose jamais aux recommandations de l\'équipe.\n\nComment je peux vous aider\n- Je connais leurs préférences, leurs peurs et ce qui les apaise.\n- Je les aide à formuler leurs questions et à comprendre vos explications.\n- Je peux rester avec la mère pendant vos absences et vous signaler un changement que j\'observe.\n\nJe respecte vos protocoles et je me retire volontiers si la situation l\'exige. Merci de votre collaboration; nous partageons le même but : une naissance sécuritaire et bien vécue.\n\n'+D.nom+', doula · Académie Sérénaissance · '+D.tel}

function dAccueil(){const D=S.doula,L=S.clients;const garde=L.filter(enGarde),pp=L.filter(c=>cStage(c).k==='pp'&&cStage(c).day<=42),pre=L.filter(c=>cStage(c).k==='preg'&&!enGarde(c));const ov=overlaps();
  const total=L.reduce((s,c)=>s+cPrice(c),0),paid=L.reduce((s,c)=>s+cPaid(c),0);
  const next=L.filter(c=>cStage(c).k==='preg').sort((a,b)=>parseD(a.dpa)-parseD(b.dpa)).slice(0,4);
  const rdvs=L.flatMap(c=>(c.rdv||[]).filter(r=>r.prochaine&&diffD(parseD(r.prochaine),new Date())>=0).map(r=>[c,r.prochaine])).sort((a,b)=>a[1].localeCompare(b[1])).slice(0,5);
  let h='<div class="card"><div class="hero"><div class="stack" style="gap:6px"><span class="script">Bonjour '+esc(D.nom.split(' ')[0])+'</span><h1>Mon tableau de bord</h1><p class="sub" style="font-family:var(--f-display);font-style:italic;color:var(--accent)">Observer, rassurer, référer</p></div><div class="blob"><img src="/doula.jpg" alt="Doula avec une maman sur un ballon"></div></div><div class="grid3"><div class="stat acc"><b>'+pre.length+'</b><span>en prénatal</span></div><div class="stat '+(garde.length?'warn':'')+'"><b>'+garde.length+'</b><span>en garde (38-42 sem.)</span></div><div class="stat ok"><b>'+pp.length+'</b><span>en post-partum</span></div></div></div>';
  if(ov.length)h+='<div class="banner gold">'+icon('fa-triangle-exclamation')+'<div class="small"><b>Dates prévues à moins de 2 semaines d\'écart :</b> '+ov.map(o=>esc(cName(o[0]))+' et '+esc(cName(o[1]))+' ('+o[2]+' j)').join(' · ')+'. Confirmez votre remplaçante.</div></div>';
  if(garde.length)h+='<div class="card" style="border-color:var(--gold)"><span class="eyebrow acc">'+icon('fa-phone')+' En garde maintenant</span>'+garde.map(c=>'<button class="cl" data-act="clientOpen" data-id="'+c.id+'" style="box-shadow:none"><div class="av">'+esc(cFirst(c)[0]||'?')+'</div><div style="flex:1;min-width:0"><b>'+esc(cName(c))+'</b><p class="xs muted">'+esc(c.lieu||'')+(c.tel?' · '+esc(c.tel):'')+'</p></div>'+stageTag(c)+'</button>').join('')+'<p class="xs muted">Téléphone chargé, sonnerie forte la nuit, plein d\'essence, sac prêt.</p></div>';
  h+='<div class="grid2 resp"><div class="card"><span class="eyebrow acc">Prochaines dates prévues</span>'+(next.length?'<div class="list">'+next.map(c=>'<div class="li"><div class="ic">'+icon('fa-baby')+'</div><div class="tx"><b>'+esc(cName(c))+'</b><span>'+fmtD(parseD(c.dpa),{day:'numeric',month:'long'})+' · garde dès le '+fmtS(addD(parseD(c.dpa),-14))+'</span></div></div>').join('')+'</div>':'<p class="small muted">Aucune.</p>')+'</div>'+
   '<div class="card"><span class="eyebrow acc">Rencontres prévues</span>'+(rdvs.length?'<div class="list">'+rdvs.map(r=>'<div class="li"><div class="ic">'+icon('fa-calendar-check')+'</div><div class="tx"><b>'+esc(cName(r[0]))+'</b><span>'+fmtD(parseD(r[1]),{weekday:'long',day:'numeric',month:'long'})+'</span></div></div>').join('')+'</div>':'<p class="small muted">Ajoutez la date de la prochaine rencontre dans chaque fiche de rencontre.</p>')+'</div></div>';
  h+='<div class="card"><span class="eyebrow acc">Paiements</span><div class="grid3"><div class="stat"><b>'+money(total)+'</b><span>forfaits signés</span></div><div class="stat ok"><b>'+money(paid)+'</b><span>reçus</span></div><div class="stat '+(total-paid>0?'warn':'')+'"><b>'+money(total-paid)+'</b><span>solde à recevoir</span></div></div><p class="xs muted">Solde complet dû au plus tard à 36 semaines.</p></div>';
  h+='<div class="tiles">'+[['clientes','','fa-user-plus','Nouvelle famille','Ouvrir un dossier','clientNew'],['outils','sac','fa-bag-shopping','Mon sac de doula','Prêt à 38 semaines'],['outils','messages','fa-message','Modèles de messages','À copier et personnaliser'],['outils','retour','fa-spa','Mon retour','Prendre soin de moi']].map(t=>'<button class="tile" data-act="'+(t[5]||'dgo')+'" data-v="'+t[0]+'|'+t[1]+'"><span class="ti">'+icon(t[2])+'</span><b>'+t[3]+'</b><span>'+t[4]+'</span></button>').join('')+'</div>';
  return h}

function dClientes(){if(S.openClient){const i=S.clients.findIndex(c=>c.id===S.openClient);if(i>=0)return dClient(i);S.openClient=null}
  const q=(S.cq||'').toLowerCase();const L=S.clients.filter(c=>!q||c.nom.toLowerCase().includes(q)).sort((a,b)=>(parseD(a.naiss)?1:0)-(parseD(b.naiss)?1:0)||(parseD(a.dpa)||0)-(parseD(b.dpa)||0));
  let h='<div class="row between">'+sh('Mes familles','Du premier contact à l\'archivage')+'<button class="btn" data-act="clientNew">'+icon('fa-plus')+'Nouvelle famille</button></div>';
  h+='<input type="text" id="cq" placeholder="Rechercher une famille" value="'+esc(S.cq||'')+'" data-act="cq">';
  if(!L.length)h+='<div class="card dash small muted" style="text-align:center">Aucune famille. Ajoutez la première avec sa date prévue.</div>';
  h+='<div class="stack">'+L.map(c=>{const n=PARCOURS.filter(x=>(c.parcours||{})[x[0]]).length;const solde=cPrice(c)-cPaid(c);
   return '<button class="cl" data-act="clientOpen" data-id="'+c.id+'"><div class="av">'+esc((cFirst(c)[0]||'?').toUpperCase())+'</div><div style="flex:1;min-width:0;display:flex;flex-direction:column;gap:5px"><div class="row between" style="gap:6px"><b>'+esc(c.nom)+'</b>'+stageTag(c)+'</div><span class="xs muted">'+(c.forfait?esc(c.forfait)+' · ':'')+(cStage(c).k==='pp'?'Naissance le '+fmtD(parseD(c.naiss)):c.dpa?'DPA '+fmtD(parseD(c.dpa)):'')+(solde>0?' · solde '+money(solde):'')+'</span><div class="prog"><i style="width:'+(n/PARCOURS.length*100)+'%"></i></div></div></button>'}).join('')+'</div>';
  return h}
const CTABS=[['resume','Dossier'],['messages','Messages'],['rdvs','Rendez-vous'],['docs','Documents'],['suivi','Suivi de la famille'],['rencontres','Fiches de rencontre'],['comms','Communications'],['travail','Accouchement'],['postnatal','Postnatal'],['paiements','Paiements'],['rempl','Remplaçante'],['mots','Mots du jour']];
function dClient(i){const c=S.clients[i],P='clients.'+i,t=S.ctab||'resume';let h=back('clientBack','','Toutes les familles');
  h+='<div class="card"><div class="row between"><div style="min-width:0"><span class="eyebrow acc">Dossier'+(c.no?' no '+esc(c.no):'')+'</span><h1>'+esc(c.nom)+'</h1></div>'+stageTag(c)+'</div><p class="small muted">'+[c.partenaire?'Partenaire : '+esc(c.partenaire):'',c.forfait?esc(c.forfait):'',c.lieu?esc(c.lieu):''].filter(Boolean).join(' · ')+'</p>'+(c.tel?'<p class="small">'+icon('fa-phone','var(--accent)')+' <b class="num" style="user-select:all">'+esc(c.tel)+'</b>'+(c.courriel?' &nbsp; '+icon('fa-envelope','var(--accent)')+' <span style="user-select:all">'+esc(c.courriel)+'</span>':'')+'</p>':'')+(c.allergies?'<div class="banner gold">'+icon('fa-triangle-exclamation')+'<div class="small"><b>Allergies :</b> '+esc(c.allergies)+'</div></div>':'')+'<div class="row"><button class="btn sm ghost" data-act="clientEdit" data-id="'+c.id+'">'+icon('fa-pen')+'Modifier</button><button class="btn sm ghost" data-act="ctab" data-v="messages">'+icon('fa-message')+'Message</button><button class="btn sm ghost" data-act="lettre" data-id="'+c.id+'">'+icon('fa-envelope-open-text')+'Lettre à l\'équipe</button></div></div>';
  h+='<div class="seg">'+CTABS.map(x=>'<button class="chip '+(t===x[0]?'on':'')+'" data-act="ctab" data-v="'+x[0]+'">'+x[1]+'</button>').join('')+'</div>';
  h+=({resume:cResume,messages:cMessages,rdvs:cRdvs,docs:cDocs,suivi:cSuivi,mots:cMots,rencontres:cRencontres,comms:cComms,travail:cTravail,postnatal:cPostnatal,paiements:cPaie,rempl:cRempl}[t]||cResume)(c,i,P);
  return h}
function cResume(c,i,P){const s=cStage(c);let h='';
  if(s.k==='preg'){const f=fruit(s.w),wi=weekInfo(s.w);const nx=EXAMS.find(e=>e[1]>=s.w);h+='<div class="card"><div class="grid3"><div class="stat acc"><b>'+s.w+' + '+s.d+'</b><span>semaines</span></div><div class="stat"><b>'+(s.left>=0?s.left:'+'+(-s.left))+'</b><span>'+(s.left>=0?'jours avant la DPA':'jours dépassés')+'</span></div><div class="stat"><b>'+fmtS(addD(parseD(c.dpa),-14))+'</b><span>début de garde (38 sem.)</span></div></div><p class="small"><b>Pour elle cette semaine :</b> '+wi[3]+'</p>'+(nx?'<p class="small"><b>Repère médical :</b> '+nx[2]+' ('+nx[0]+(nx[1]!==nx[0]?'-'+nx[1]:'')+' SA)</p>':'')+'<p class="small"><b>Taille de bébé :</b> '+esc(f[0])+'</p></div>';
   const rn=s.w<28?RENCONTRES[1]:s.w<32?RENCONTRES[1]:s.w<36?RENCONTRES[2]:s.w<38?RENCONTRES[3]:RENCONTRES[4];h+='<div class="card tint"><span class="eyebrow acc">Étape suggérée maintenant</span><h3>'+rn[0]+'</h3><p class="small">'+rn[2]+'</p><p class="xs muted">À remettre : '+rn[4]+'</p></div>'}
  if(s.k==='pp'){const inf=ppInfo(s.day);h+='<div class="card"><div class="grid2"><div class="stat ok"><b>Jour '+s.day+'</b><span>post-partum'+(c.bebe?' · '+esc(c.bebe):'')+'</span></div><div class="stat"><b style="font-size:1rem">'+inf[1]+'</b><span>étape</span></div></div><p class="small"><b>Maman :</b> '+inf[3]+'</p></div>'}
  if(c.notes)h+='<div class="card"><span class="eyebrow acc">Notes</span><p class="small">'+esc(c.notes).replace(/\n/g,'<br>')+'</p></div>';

  h+='<div class="card"><span class="eyebrow acc">Parcours de A à Z</span><div class="timeline">'+PARCOURS.map(x=>{const d=(c.parcours||{})[x[0]];return '<div class="tl '+(d?'done':'')+'"><div class="row between" style="gap:6px"><b>'+x[1]+'</b><input type="date" style="width:auto;padding:5px 8px;font-size:.8rem" data-act="txt" data-rr="1" data-p="'+P+'.parcours.'+x[0]+'" value="'+esc(d||'')+'" aria-label="Date : '+esc(x[1])+'"></div><p class="xs muted">'+x[2]+'</p></div>'}).join('')+'</div></div>';
  h+='<details class="acc"><summary>'+icon('fa-folder-open','var(--accent)')+'Documents au dossier <span class="pill acc">'+ui.count(P+'.docs',DOCS_DOSSIER)+'/'+DOCS_DOSSIER.length+'</span><i class="fa-solid fa-chevron-down chev"></i></summary><div class="body">'+ui.checks(P+'.docs',DOCS_DOSSIER)+ui.text(P+'.destruction','Destruction du dossier prévue le','date')+'</div></details>';
  h+=statutCard(c);return h}

function cRencontres(c,i,P){let h='<div class="row between"><span class="eyebrow acc">Fiches de rencontre</span><button class="btn sm" data-act="rdvNew" data-id="'+c.id+'">'+icon('fa-plus')+'Nouvelle fiche</button></div>';
  const R=(c.rdv||[]).slice().sort((a,b)=>(b.date||'').localeCompare(a.date||''));
  if(!R.length)h+='<div class="card dash small muted">Aucune rencontre notée. Une fiche par rencontre, remplie le jour même.</div>';
  R.forEach(r=>{h+='<details class="acc"><summary>'+icon('fa-calendar-check','var(--accent)')+'<span style="min-width:0">'+esc(r.type)+'<br><span class="xs muted" style="font-weight:500">'+fmtD(parseD(r.date))+(r.duree?' · '+esc(r.duree):'')+'</span></span>'+(r.alerte==='Oui'?'<span class="pill bad">Signal</span>':'')+'<i class="fa-solid fa-chevron-down chev"></i></summary><div class="body">'+(r.meteo?'<p class="small"><b>Comment vont les parents :</b> '+esc(r.meteo)+'</p>':'')+(r.medical?'<p class="small"><b>Suivi médical (rapporté) :</b> '+esc(r.medical)+'</p>':'')+(Object.keys(r.sujets||{}).filter(k=>r.sujets[k]).length?'<p class="small"><b>Sujets :</b> '+esc(Object.keys(r.sujets).filter(k=>r.sujets[k]).join(', '))+'</p>':'')+(Object.keys(r.outils||{}).filter(k=>r.outils[k]).length?'<p class="small"><b>Outils remis :</b> '+esc(Object.keys(r.outils).filter(k=>r.outils[k]).join(', '))+'</p>':'')+(r.obs?'<p class="small"><b>Mes observations :</b> '+esc(r.obs)+'</p>':'')+(r.alerte==='Oui'?'<p class="small"><b>Signal d\'alerte · orientation :</b> '+esc(r.orientation||'')+'</p>':'')+(r.afaire?'<p class="small"><b>À faire :</b> '+esc(r.afaire)+'</p>':'')+(r.prochaine?'<p class="small"><b>Prochaine rencontre :</b> '+fmtD(parseD(r.prochaine))+'</p>':'')+'<div class="row"><button class="btn sm ghost" data-act="rdvEdit" data-id="'+c.id+'" data-r="'+r.id+'">'+icon('fa-pen')+'Modifier</button><button class="btn sm danger" data-act="rdvDel" data-id="'+c.id+'" data-r="'+r.id+'">Supprimer</button></div></div></details>'});
  h+='<details class="acc"><summary>'+icon('fa-cloud','var(--accent)')+'Peurs et besoins (score 0 à 4)<i class="fa-solid fa-chevron-down chev"></i></summary><div class="body">'+PEURS.map(x=>'<div class="row between" style="gap:6px"><span class="small">'+x+'</span><div class="tri">'+[0,1,2,3,4].map(n=>'<button class="chip '+((c.peurs||{})[x]===n?'on':'')+'" data-act="cpeur" data-id="'+c.id+'" data-k="'+esc(x)+'" data-v="'+n+'">'+n+'</button>').join('')+'</div></div>').join('')+ui.area(P+'.peursPlan','Plan convenu','',60)+'<p class="xs muted">Peurs à 3 ou 4 : en parler à la prochaine rencontre. Vécu traumatique, anxiété qui empêche de dormir ou de fonctionner : suggérer d\'en parler au médecin, au CLSC ou à un psychologue.</p></div></details>';
  return h}
function cComms(c,i,P){const M={A:'Appel',T:'Texto',M:'Messenger',C:'Courriel'};let h='<div class="row between"><span class="eyebrow acc">Journal des communications</span><button class="btn sm" data-act="commNew" data-id="'+c.id+'">'+icon('fa-plus')+'Noter</button></div><p class="xs muted">Noté le jour même. Pendant la garde : heure exacte, rythme des contractions, eaux, saignements, mouvements du bébé, ce que j\'ai recommandé. Jamais de conseil médical par texto.</p>';
  const L=(c.comms||[]).slice().sort((a,b)=>b.t-a.t);h+=L.length?'<div class="card flat" style="gap:0"><div class="list">'+L.map(m=>'<div class="li"><div class="ic">'+icon({A:'fa-phone',T:'fa-comment-sms',M:'fa-comments',C:'fa-envelope'}[m.mode]||'fa-comment')+'</div><div class="tx"><b>'+(M[m.mode]||'')+' · '+fmtS(new Date(m.t))+' '+fmtT(m.t)+(m.duree?' · '+esc(m.duree):'')+'</b><span>'+esc(m.motif)+(m.orient?' · <i>Orientation : '+esc(m.orient)+'</i>':'')+'</span></div><button class="icon-btn" data-act="commDel" data-id="'+c.id+'" data-r="'+m.id+'" aria-label="Supprimer">'+icon('fa-trash')+'</button></div>').join('')+'</div></div>':'<div class="card dash small muted">Aucune communication notée.</div>';return h}
function cTravail(c,i,P){let h='';
  h+='<div class="card"><div class="row between"><span class="eyebrow acc">Appels pendant le travail</span><button class="btn sm" data-act="appelNew" data-id="'+c.id+'">'+icon('fa-phone')+'Nouvel appel</button></div>'+((c.appels||[]).length?'<div class="list">'+c.appels.map((a,k)=>'<div class="li"><div class="ic">'+icon('fa-phone')+'</div><div class="tx"><b>Appel '+(k+1)+' · '+fmtT(a.t)+'</b><span>'+esc(a.decision||'')+(a.conseils?' · '+esc(a.conseils):'')+'</span></div><button class="icon-btn" data-act="appelDel" data-id="'+c.id+'" data-r="'+a.id+'" aria-label="Supprimer">'+icon('fa-trash')+'</button></div>').join('')+'</div>':'<p class="xs muted">Les 10 questions à poser, les signaux qui orientent vers l\'hôpital ou le 911, et votre décision.</p>')+'</div>';
  const M=c.moments||{};h+='<div class="card"><span class="eyebrow acc">Journal de l\'accouchement · les grands moments</span><div class="list">'+MOMENTS.map((m,k)=>'<div class="li"><div class="tx"><b>'+m+'</b></div><input type="time" style="width:auto;padding:5px 8px;font-size:.85rem" data-act="txt" data-p="'+P+'.moments.m'+k+'" value="'+esc(M['m'+k]||'')+'" aria-label="Heure : '+esc(m)+'"><button class="btn sm ghost" data-act="momentNow" data-id="'+c.id+'" data-k="m'+k+'">Maintenant</button></div>').join('')+'</div></div>';
  h+='<div class="card"><div class="row between"><span class="eyebrow acc">Heure par heure</span><button class="btn sm" data-act="hpdNew" data-id="'+c.id+'">'+icon('fa-plus')+'Ajouter</button></div>'+((c.hpd||[]).length?'<div class="scroll-x"><table class="tbl"><thead><tr><th>Heure</th><th>Ce qui se passe</th><th>Confort offert</th><th>Ce qui a aidé</th><th></th></tr></thead><tbody>'+c.hpd.slice().sort((a,b)=>a.t-b.t).map(e=>'<tr><td class="num"><b>'+hm(e.t)+'</b></td><td>'+esc(e.quoi)+'</td><td>'+esc(e.confort)+'</td><td>'+esc(e.aide)+'</td><td><button class="icon-btn" data-act="hpdDel" data-id="'+c.id+'" data-r="'+e.id+'" aria-label="Supprimer">'+icon('fa-trash')+'</button></td></tr>').join('')+'</tbody></table></div>':'<p class="xs muted">Faits observés, sans interprétation clinique.</p>')+'</div>';
  h+='<div class="card"><span class="eyebrow acc">Naissance</span><div class="grid2 resp">'+ui.text(P+'.naiss','Date de naissance','date',0,1)+ui.text(P+'.bebe','Prénom du bébé')+'</div><span class="small"><b>Type</b></span>'+ui.pick(P+'.typeNaiss',['Vaginale','Instrumentée','Césarienne'])+'</div>';
  h+='<button class="btn ghost" data-act="lettre" data-id="'+c.id+'">'+icon('fa-envelope-open-text')+'Lettre de présentation à l\'équipe soignante</button>';return h}
function cPostnatal(c,i,P){let h='';const s=cStage(c);
  h+='<div class="card"><span class="eyebrow acc">Appels de suivi postnatal</span><p class="xs muted">Trois appels de 10 à 20 minutes entre les visites.</p>'+APPELS_PN.map(a=>'<div class="soft"><div class="row between"><b class="small">'+a[1]+(s.k==='pp'?' · '+fmtS(addD(parseD(c.naiss),a[0]==='j1'?1:a[0]==='j3'?3:14)):'')+'</b>'+((c.pn||{})[a[0]]&&(c.pn[a[0]].date)?'<span class="pill sage">Fait</span>':'')+'</div><p class="xs muted">'+a[2]+'</p><div class="grid2">'+ui.text(P+'.pn.'+a[0]+'.date','Date','date')+ui.text(P+'.pn.'+a[0]+'.orient','Orientée vers')+'</div>'+ui.area(P+'.pn.'+a[0]+'.obs','Mes observations','',50)+'<div class="grid2"><div><span class="xs"><b>Repérage maman</b></span>'+ui.pick(P+'.pn.'+a[0]+'.mere',['RAS','Orientée'])+'</div><div><span class="xs"><b>Repérage bébé</b></span>'+ui.pick(P+'.pn.'+a[0]+'.bebe',['RAS','Orientée'])+'</div></div></div>').join('')+'<div class="banner acc">'+icon('fa-comments')+'<div class="small"><b>À chaque appel, le moral :</b> « Depuis notre dernier échange, t\'es-tu sentie triste, vide ou sans espoir ? As-tu perdu l\'intérêt pour ce que tu aimais ? » Si oui presque tous les jours depuis 2 semaines : médecin, CLSC ou 811. Idées de se faire du mal : 988 ou 911 immédiatement.</div></div></div>';
  h+='<div class="card"><div class="row between"><span class="eyebrow acc">Visites postnatales</span><button class="btn sm" data-act="visiteNew" data-id="'+c.id+'">'+icon('fa-plus')+'Nouvelle visite</button></div>'+((c.visites||[]).length?c.visites.map(v=>{const fm=Object.keys(v.mere||{}).filter(k=>v.mere[k]),fb=Object.keys(v.bebe||{}).filter(k=>v.bebe[k]);return '<div class="soft"><div class="row between"><b class="small">'+fmtD(parseD(v.date))+(v.jours?' · jour '+esc(v.jours):'')+'</b>'+(fm.length||fb.length?'<span class="pill bad">'+(fm.length+fb.length)+' signal(aux)</span>':'<span class="pill sage">Aucun signal</span>')+'</div>'+(fm.length?'<p class="xs"><b>Mère :</b> '+esc(fm.join(' · '))+'</p>':'')+(fb.length?'<p class="xs"><b>Bébé :</b> '+esc(fb.join(' · '))+'</p>':'')+(v.orient?'<p class="xs"><b>Orientée vers :</b> '+esc(v.orient)+'</p>':'')+(v.alim?'<p class="xs"><b>Alimentation :</b> '+esc(v.alim)+'</p>':'')+(v.obs?'<p class="xs"><b>Observations :</b> '+esc(v.obs)+'</p>':'')+'<button class="btn sm danger" data-act="visiteDel" data-id="'+c.id+'" data-r="'+v.id+'" style="align-self:flex-start">Supprimer</button></div>'}).join(''):'<p class="xs muted">Repérage mère et bébé, tétée observée, récupération, moral, partenaire et fratrie.</p>')+'</div>';
  h+='<details class="acc"><summary>'+icon('fa-feather','var(--accent)')+'Séance de retour sur la naissance<i class="fa-solid fa-chevron-down chev"></i></summary><div class="body"><p class="xs muted">Vers 2 à 6 semaines, au calme, sans pression. Les parents peuvent refuser ou arrêter en tout temps. Écouter sans corriger ni juger; ne jamais expliquer les décisions médicales à la place de l\'équipe.</p><ul class="clean small">'+RETOUR_NAISS.map(q=>'<li>'+q+'</li>').join('')+'</ul>'+ui.text(P+'.retourN.date','Date','date')+ui.area(P+'.retourN.notes','Mes notes','',80)+'<p class="xs muted">Orienter si cauchemars, retours en arrière, évitement, détresse de plus d\'un mois, peur intense d\'une prochaine grossesse : médecin, CLSC, psychologue en périnatalité.</p></div></details>';
  h+='<button class="btn ghost" data-act="ctab" data-v="messages">'+icon('fa-envelope')+'Messages et lettre de fin</button>';return h}
function cPaie(c,i,P){const F=FORFAITS[c.forfait];const paid=cPaid(c),price=cPrice(c);let h='<div class="card"><span class="eyebrow acc">Forfait</span>'+ui.pick(P+'.forfait',Object.keys(FORFAITS))+(F?'<p class="xs muted">'+F.desc+'. Valeur : accouchement '+money(F.acc)+' · rencontre '+money(F.renc)+'.</p>':'')+'<div class="grid3"><div class="stat"><b>'+money(price)+'</b><span>forfait</span></div><div class="stat ok"><b>'+money(paid)+'</b><span>reçu</span></div><div class="stat '+(price-paid>0?'warn':'')+'"><b>'+money(price-paid)+'</b><span>solde (dû à 36 sem.)</span></div></div></div>';
  h+='<div class="card"><div class="row between"><span class="eyebrow acc">Versements et reçus</span><button class="btn sm" data-act="paieNew" data-id="'+c.id+'">'+icon('fa-plus')+'Versement</button></div>'+((c.paie||[]).length?'<div class="list">'+c.paie.map((p,k)=>'<div class="li"><div class="ic">'+icon('fa-receipt')+'</div><div class="tx"><b>'+money(p.montant)+' · '+fmtD(parseD(p.date),{day:'numeric',month:'short',year:'numeric'})+'</b><span>'+esc(p.mode||'')+(p.no?' · reçu no '+esc(p.no):'')+'</span></div><button class="btn sm ghost" data-act="recu" data-id="'+c.id+'" data-r="'+p.id+'">Reçu</button><button class="icon-btn" data-act="paieDel" data-id="'+c.id+'" data-r="'+p.id+'" aria-label="Supprimer">'+icon('fa-trash')+'</button></div>').join('')+'</div>':'<p class="xs muted">Aucun versement.</p>')+'<p class="xs muted">Retard de plus de 14 jours : rappel écrit; la garde peut être suspendue jusqu\'au paiement. Les services de doula peuvent être admissibles à certaines assurances collectives : la famille vérifie auprès de son assureur.</p></div>';
  h+='<details class="acc"><summary>'+icon('fa-calculator','var(--accent)')+'Calcul d\'un remboursement (article 9)<i class="fa-solid fa-chevron-down chev"></i></summary><div class="body">'+ui.text(P+'.remb.rendus','Valeur des services rendus ($, annexe A)','number',0,1)+(()=>{const r=+((c.remb||{}).rendus)||0;const non=Math.max(0,price-r);const pen=Math.min(50,non*.1);return '<div class="grid3"><div class="stat"><b>'+money(non)+'</b><span>non rendus</span></div><div class="stat"><b>'+money(pen)+'</b><span>pénalité (50 $ ou 10 %, le plus petit)</span></div><div class="stat acc"><b>'+money(Math.max(0,paid-r-pen))+'</b><span>remboursement dû</span></div></div>'})()+'<p class="xs muted">Avant la première rencontre : remboursement complet. Remboursé dans les 10 jours suivant l\'avis écrit, par le même moyen.</p></div></details>';return h}
function cRempl(c,i,P){return '<div class="card"><span class="eyebrow acc">Transmission à la remplaçante</span><p class="xs muted">Remplie à 37 semaines, transmise seulement si les parents ont consenti au partage de leur dossier. Confidentielle.</p><div class="grid2 resp">'+TRANSMISSION.map(t=>ui.text(P+'.transm.'+t[0],t[1])).join('')+'</div><span class="small"><b>Autorisation photos</b></span>'+ui.pick(P+'.transm.photos',['Oui','Non'])+ui.text(P+'.transm.connait','Les parents connaissent la remplaçante (nom, rencontre le…)')+'<button class="btn sm ghost" data-act="copyTransm" data-id="'+c.id+'">'+icon('fa-copy')+'Copier la fiche</button><p class="xs muted">Après l\'accouchement : compte rendu dans les 48 heures avec le journal de l\'accouchement. Documents remis ou détruits; aucune copie conservée.</p></div>'}

function dAgenda(){let h=sh('Mon agenda','Calendrier des dates prévues et de mes gardes');const ov=overlaps();
  if(ov.length)h+='<div class="banner gold">'+icon('fa-triangle-exclamation')+'<div class="small">Évitez deux familles dont les dates prévues sont à moins de 2 semaines d\'écart, sauf si votre remplaçante est confirmée : '+ov.map(o=>esc(cName(o[0]))+' / '+esc(cName(o[1])))+'.</div></div>';
  const start=new Date();start.setDate(1);for(let m=0;m<12;m++){const a=new Date(start.getFullYear(),start.getMonth()+m,1),b=new Date(a.getFullYear(),a.getMonth()+1,0);
   const L=S.clients.filter(c=>{const d=parseD(c.dpa);if(!d||parseD(c.naiss))return false;const g1=addD(d,-14),g2=addD(d,14);return g1<=b&&g2>=a});
   const R=S.clients.flatMap(c=>(c.rdv||[]).filter(r=>{const d=parseD(r.prochaine);return d&&d>=a&&d<=b}).map(r=>[c,r.prochaine]));
   if(!L.length&&!R.length&&m>2)continue;
   h+='<div class="card"><span class="eyebrow acc">'+a.toLocaleDateString('fr-CA',{month:'long',year:'numeric'})+'</span>'+(L.length||R.length?'<div class="list">'+L.map(c=>'<div class="li"><div class="ic">'+icon('fa-phone')+'</div><div class="tx"><b>'+esc(cName(c))+'</b><span>Garde du '+fmtS(addD(parseD(c.dpa),-14))+' au '+fmtS(addD(parseD(c.dpa),14))+' · DPA '+fmtS(parseD(c.dpa))+'</span></div></div>').join('')+R.map(r=>'<div class="li"><div class="ic">'+icon('fa-calendar-check')+'</div><div class="tx"><b>Rencontre · '+esc(cName(r[0]))+'</b><span>'+fmtD(parseD(r[1]),{weekday:'long',day:'numeric'})+'</span></div></div>').join('')+'</div>':'<p class="small muted">Rien de prévu.</p>')+'</div>'}
  h+='<div class="card"><span class="eyebrow acc">Mes vacances et indisponibilités</span>'+ui.area('doula.indispo','','Ex. : 1er au 15 juillet',60)+'</div>';return h}

const DOUT=[['modeles','fa-file-signature','Mes modèles de documents','Contrat et formulaires à ton image'],['sac','fa-bag-shopping','Mon sac de doula','Prêt à 38 semaines'],['contr','fa-stopwatch','Minuteur de contractions','Repère 5-1-1'],['calc','fa-calculator','Calculatrice DPA','Âge gestationnel à une date'],['rencontres','fa-people-group','Déroulement des rencontres','Entrevue à la clôture'],['approche','fa-handshake','Rencontre d\'approche','Appel, entrevue, suivi'],['messages','fa-message','Modèles de messages','11 messages prêts'],['lettre','fa-envelope-open-text','Lettre à l\'équipe','Présentation de la doula'],['positions','fa-person-walking','Positions','Par étape du travail'],['confort','fa-spa','Confort et douleur','Mesures et options'],['partenaire','fa-people-arrows','Guide du partenaire','Pressions, mots, sécurité'],['retour','fa-leaf','Mon retour','Après chaque accompagnement'],['profil','fa-id-card','Mon profil','Nom, téléphone, remplaçante']];
function dOutils(){const s=S.dsub;if(s&&DSUB[s])return back('dsub','','Outils')+DSUB[s]();
  return sh('Ma boîte à outils','Tous les documents de la trousse, prêts à utiliser')+'<div class="tiles">'+DOUT.map(t=>'<button class="tile" data-act="dsub" data-v="'+t[0]+'"><span class="ti">'+icon(t[1])+'</span><b>'+t[2]+'</b><span>'+t[3]+'</span></button>').join('')+'</div>'}
const DSUB={
 sac(){const all=Object.values(SAC_DOULA).flat();return sh('Mon sac de doula','Prêt à 38 semaines')+'<div class="card tint"><div class="row between"><b>'+ui.count('doula.sac',all)+' / '+all.length+' prêts</b><button class="btn sm ghost" data-act="sacReset">Tout décocher</button></div><div class="prog"><i style="width:'+(ui.count('doula.sac',all)/all.length*100)+'%"></i></div></div>'+Object.entries(SAC_DOULA).map(([k,v])=>'<div class="card"><span class="eyebrow acc">'+k+'</span>'+ui.checks('doula.sac',v)+'</div>').join('')},
 contr(){return sh('Minuteur de contractions','Pour accompagner la famille au téléphone ou sur place')+contrCard(true)},
 calc(){const C=S.calc||{};const ddr=parseD(C.ddr),dpa=parseD(C.dpa)||(ddr?addD(ddr,280+((+C.cycle||28)-28)):null),at=parseD(C.at)||new Date();let r='';
  if(dpa){const [w,d]=gaAt(dpa,at);r='<div class="grid2"><div class="stat acc"><b>'+fmtD(dpa,{day:'numeric',month:'short',year:'numeric'})+'</b><span>date prévue</span></div><div class="stat"><b>'+w+' SA + '+d+' j</b><span>au '+fmtS(at)+'</span></div></div><div class="grid3"><div class="stat"><b>'+fmtS(addD(dpa,-21))+'</b><span>37 SA · à terme</span></div><div class="stat"><b>'+fmtS(addD(dpa,-14))+'</b><span>38 SA · garde</span></div><div class="stat"><b>'+fmtS(addD(dpa,14))+'</b><span>42 SA · fin de garde</span></div></div>'}
  return sh('Calculatrice DPA','')+'<div class="card"><div class="grid2 resp">'+ui.text('calc.ddr','Dernières règles','date',0,1)+ui.text('calc.cycle','Cycle (jours)','number','28',1)+ui.text('calc.dpa','ou date prévue connue','date',0,1)+ui.text('calc.at','Âge gestationnel au','date',0,1)+'</div>'+r+'</div>'},
 rencontres(){return sh('Déroulement de mes rencontres','Durée type 1 h 30 à 2 h; l\'entrevue, 45 min à 1 h')+'<div class="card tint"><span class="eyebrow acc">Structure type (environ 2 h)</span><div class="list">'+STRUCT_RENC.map(s=>'<div class="li"><div class="tx"><b>'+s[0]+'</b></div><span class="pill line">'+s[1]+'</span></div>').join('')+'</div><p class="xs muted">Soutien au Couple : rencontres 1 à 3 condensées en une. Arrivée de Bébé : rencontre de connaissance seulement. Au moins une rencontre à la maison aide à connaître l\'environnement et le trajet.</p></div>'+RENCONTRES.map(r=>'<details class="acc"><summary><span style="min-width:0">'+r[0]+'<br><span class="xs muted" style="font-weight:500">'+r[1]+'</span></span><i class="fa-solid fa-chevron-down chev"></i></summary><div class="body"><p class="small"><i>'+r[2]+'</i></p><ul class="clean small">'+r[3].map(x=>'<li>'+x+'</li>').join('')+'</ul><p class="xs"><b>À remettre :</b> '+r[4]+'</p></div></details>').join('')+'<div class="card"><span class="eyebrow acc">Variantes</span><ul class="clean small"><li><b>Arrive après 36 semaines :</b> entrevue + une rencontre de 2 h 30 sur le jour J et le confort; garde dès la signature.</li><li><b>Césarienne planifiée :</b> rencontre 2 centrée sur la césarienne, les souhaits possibles et la récupération.</li><li><b>Projet d\'AVAC :</b> écouter le récit de la césarienne précédente; préparer les questions pour le médecin.</li><li><b>2e bébé ou plus :</b> revisiter la naissance précédente; travail souvent plus rapide; garde des aînés.</li><li><b>Suivi particulier :</b> le professionnel reste la référence; renforcer les signaux d\'alerte.</li><li><b>À distance :</b> fiches envoyées à l\'avance, appel de pratique des gestes avec le partenaire.</li></ul></div>'},
 approche(){let h=sh('Rencontre d\'approche','Écouter, être honnête, laisser la famille libre. La famille parle environ les deux tiers du temps.');
  h+='<div class="card"><span class="eyebrow acc">Le court appel (10 à 15 min)</span><div class="list">'+QUESTIONS_APPEL.map(q=>'<div class="li"><div class="tx"><b>'+q[0]+'</b><span>'+q[1]+'</span></div></div>').join('')+'</div></div>';
  h+='<div class="card"><span class="eyebrow acc">L\'entrevue en cinq temps</span><div class="list">'+[['L\'accueil','5 min'],['Faire connaissance','20 min'],['Mon rôle et mes services','15 min'],['Leurs questions','15 min'],['La suite, sans pression','5 min']].map(x=>'<div class="li"><div class="tx"><b>'+x[0]+'</b></div><span class="pill line">'+x[1]+'</span></div>').join('')+'</div></div>';
  h+=Object.entries(QUESTIONS_ENTREVUE).map(([k,v])=>'<details class="acc"><summary>Questions · '+k+'<i class="fa-solid fa-chevron-down chev"></i></summary><div class="body"><ul class="clean small">'+v.map(x=>'<li>'+x+'</li>').join('')+'</ul></div></details>').join('');
  h+='<div class="card"><span class="eyebrow acc">Phrases qui aident</span><div class="soft"><b class="small">Pour présenter mon rôle</b><p class="small"><i>« Mon rôle, c\'est de vous soutenir émotionnellement et physiquement, de vous aider à comprendre ce qui se passe et à poser vos questions. Je ne fais aucun geste médical. »</i></p></div><div class="soft"><b class="small">Pour la confidentialité</b><p class="small"><i>« Tout ce que vous me confiez reste confidentiel, sauf si une vie est en danger ou si la sécurité d\'un enfant est menacée. »</i></p></div><div class="soft"><b class="small">Pour fermer</b><p class="small"><i>« Prenez le temps d\'en parler ensemble, il n\'y a aucune urgence. Et si vous choisissez quelqu\'un d\'autre, ce sera correct aussi. »</i></p></div></div>';
  h+='<div class="card"><span class="eyebrow acc">Signaux à repérer</span><div class="list">'+SIGNAUX_ENTREVUE.map(s=>'<div class="li"><div class="tx"><b>'+s[0]+'</b><span>'+s[1]+'</span></div></div>').join('')+'</div></div>';
  h+='<div class="banner acc">'+icon('fa-compass')+'<div class="small"><b>Mon aide-mémoire :</b> écouter plus que parler · aucun avis médical · garde de 38 à 42 semaines · jamais de transport · 18 ans et plus · jamais sans médecin ni sage-femme · confidentialité et ses limites dites dès le départ · aucune pression · un merci en 24 h, un seul rappel.</div></div>';return h},
 messages(){const c=S.clients.find(x=>x.id===S.msgClient);let h=sh('Modèles de messages','À copier et personnaliser');
  h+='<label class="f">Pour quelle famille ?<select id="msgSel" data-act="msgSel"><option value="">Aucune (garder les crochets)</option>'+S.clients.map(x=>'<option value="'+x.id+'" '+(c&&c.id===x.id?'selected':'')+'>'+esc(x.nom)+'</option>').join('')+'</select></label>';
  h+=MESSAGES.map((m,k)=>{const t=fillMsg(m[1],c);return '<div class="card"><div class="row between"><b>'+m[0]+'</b><button class="btn sm ghost" data-act="copyEl" data-v="m'+k+'">'+icon('fa-copy')+'Copier</button></div><pre class="msg" id="m'+k+'">'+esc(t)+'</pre></div>'}).join('');
  const fin='Chère '+(c?cFirst(c):'____________')+',\n\nNotre accompagnement se termine aujourd\'hui, et je tenais à vous dire merci. Merci de m\'avoir ouvert la porte de votre histoire et de votre maison.\n\nJ\'ai été témoin de votre courage, de votre douceur et de tout l\'amour qui entoure '+((c&&c.bebe)||'____________')+'. Ces souvenirs resteront précieux pour moi.\n\nLes prochaines semaines apporteront encore des découvertes. Rappelez-vous que vous n\'avez pas à tout savoir : demander de l\'aide est un geste de force.\n\nMa porte reste ouverte. Si vous avez besoin de parler, d\'une marraine d\'allaitement ou d\'une référence, écrivez-moi.\n\n'+S.doula.nom+'\n'+S.doula.tel+' · '+S.doula.courriel+' · academiesere.ca';
  h+='<div class="card"><div class="row between"><b>Lettre de fin d\'accompagnement</b><button class="btn sm ghost" data-act="copyEl" data-v="mfin">'+icon('fa-copy')+'Copier</button></div><pre class="msg" id="mfin">'+esc(fin)+'</pre></div>';return h},
 lettre(){const c=S.clients.find(x=>x.id===S.msgClient);return sh('Lettre de présentation à l\'équipe','À remettre au poste en deux copies : une pour les infirmières, une au dossier')+'<label class="f">Pour quelle famille ?<select id="msgSel2" data-act="msgSel"><option value="">Choisir…</option>'+S.clients.map(x=>'<option value="'+x.id+'" '+(c&&c.id===x.id?'selected':'')+'>'+esc(x.nom)+'</option>').join('')+'</select></label><div class="card"><pre class="msg" id="lt">'+esc(lettreEquipe(c))+'</pre><button class="btn" data-act="copyEl" data-v="lt">'+icon('fa-copy')+'Copier la lettre</button></div>'},
 positions:()=>PSUB.positions(), partenaire:()=>PSUB.partenaire(), confort:()=>fichePage(FICHES.find(f=>f.id==='A3')),
 retour(){return sh('Mon retour après un accompagnement','Pour moi seulement; aucun nom complet')+'<div class="card"><div class="grid2 resp">'+ui.text('doula.retour.quand','Famille (initiales) · date de naissance')+ui.text('doula.retour.duree','Durée totale de ma présence')+'</div><span class="small"><b>Fatigue</b></span>'+ui.pick('doula.retour.fatigue',['0','1','2','3','4'])+'<span class="small"><b>Émotions</b></span>'+ui.pick('doula.retour.emotions',['0','1','2','3','4'])+ui.area('doula.retour.bien','Ce qui s\'est bien passé','',60)+ui.area('doula.retour.autrement','Ce que j\'aurais fait autrement','',60)+ui.area('doula.retour.equipe','Ma collaboration avec l\'équipe','',60)+ui.area('doula.retour.ressens','Ce que je ressens, ce dont j\'ai besoin','',60)+ui.text('doula.retour.formation','Formation ou lecture à faire')+'</div><div class="card tint"><span class="eyebrow acc">Prendre soin de moi</span><ul class="clean small"><li>Dormir et manger avant toute autre chose</li><li>En parler à une collègue, ma remplaçante ou ma superviseure (sans nommer la famille)</li><li>Après une naissance difficile ou un deuil : prévoir du soutien professionnel</li></ul></div>'},
 profil(){return sh('Mon profil de doula','Utilisé dans les messages, la lettre à l\'équipe et les reçus')+'<div class="card"><div class="grid2 resp">'+ui.text('doula.nom','Mon nom')+ui.text('doula.tel','Mon téléphone','tel')+ui.text('doula.courriel','Mon courriel','email')+ui.text('doula.region','Ma région')+ui.text('doula.rempNom','Ma remplaçante')+ui.text('doula.rempTel','Téléphone de la remplaçante','tel')+ui.text('doula.tvh','No de TVH (ou « non inscrite »)')+'</div></div>'}
};
function dRessources(){const s=S.dsub2;let h=sh('Ressources','Mon cadre de pratique et mes repères');
  h+='<div class="card"><span class="eyebrow acc">Annexe B · Observer et référer</span><div class="grid2 resp"><div class="soft"><b class="small">'+icon('fa-check','var(--sage-dk)')+' La doula peut</b><ul class="clean xs"><li>Offrir soutien émotionnel, réconfort, écoute</li><li>Proposer positions, respiration, massages, confort</li><li>Fournir de l\'information de sources reconnues</li><li>Aider les parents à formuler leurs questions</li><li>Soutenir l\'allaitement et les premiers soins</li><li>Reconnaître les signaux d\'alerte et orienter</li><li>Appeler l\'hôpital ou le 911 sans attendre</li></ul></div><div class="soft"><b class="small">'+icon('fa-xmark','var(--bad)')+' La doula ne peut pas</b><ul class="clean xs"><li>Examen vaginal, tension, cœur du bébé</li><li>Poser un diagnostic, interpréter un résultat</li><li>Recommander un médicament, une plante, un produit</li><li>Parler ou décider à la place des parents</li><li>Remplacer sage-femme, infirmière, IBCLC, médecin</li><li>Retarder une consultation ou un appel au 911</li></ul></div></div></div>';
  h+='<details class="acc"><summary>'+icon('fa-triangle-exclamation','var(--bad)')+'Repérage maman et bébé<i class="fa-solid fa-chevron-down chev"></i></summary><div class="body"><b class="small">La mère</b><ul class="clean xs">'+REPERAGE_MERE.map(x=>'<li>'+x+'</li>').join('')+'</ul><b class="small">Le bébé</b><ul class="clean xs">'+REPERAGE_BEBE.map(x=>'<li>'+x+'</li>').join('')+'</ul><b class="small">Pendant le travail : hôpital ou 911 sans attendre</b><p class="xs">'+APPEL_ROUGE+'</p></div></details>';
  h+='<details class="acc"><summary>'+icon('fa-comments','var(--accent)')+'Repérage du moral postnatal<i class="fa-solid fa-chevron-down chev"></i></summary><div class="body"><p class="small"><b>Deux questions à chaque contact</b> (depuis les deux dernières semaines) : t\'es-tu souvent sentie triste, déprimée ou sans espoir ? As-tu eu peu d\'intérêt ou de plaisir à faire les choses ?</p><p class="small">Un « oui » : poursuivre la discussion et suggérer une évaluation au médecin, au CLSC ou au 811. Posez-les aussi au partenaire.</p><p class="small"><b>Urgence immédiate (911 ou 988) :</b> idées de se faire du mal ou de faire du mal au bébé; confusion, voir ou entendre des choses, ne plus dormir du tout; agitation extrême, propos étranges.</p><p class="xs muted">L\'échelle d\'Édimbourg (EPDS) est un outil reconnu de dépistage : utilisez la version française officielle, remise par le CLSC ou le médecin. Elle ne sert pas à poser un diagnostic.</p></div></details>';
  h+='<details class="acc"><summary>'+icon('fa-location-dot','var(--accent)')+'Ressources par région<i class="fa-solid fa-chevron-down chev"></i></summary><div class="body"><p class="small"><b>Nouveau-Brunswick :</b> Télé-Soins 811 · Santé publique N.-B. (suivi postnatal, allaitement, vaccination) · Service Nouveau-Brunswick (naissance)</p><p class="small"><b>Québec :</b> Info-Santé et Info-Social 811 · CLSC (visite postnatale, cliniques d\'allaitement) · Nourri-Source · Mieux vivre avec notre enfant · Fondation OLO</p><p class="small"><b>Partout au Canada :</b> 911 · 988 · Ligue La Leche Canada · Soins de nos enfants · votre pharmacien</p><p class="small"><b>France :</b> 15 SAMU · 112 · 116 117 médecin de garde · 3114 · PMI · 1000 premiers jours · entretien prénatal précoce et séances de préparation avec une sage-femme (Assurance maladie)</p><p class="small"><b>Académie Sérénaissance :</b> marraines d\'allaitement, jumelage gratuit</p></div></details>';
  h+='<details class="acc"><summary>'+icon('fa-lock','var(--accent)')+'Gestion des dossiers et confidentialité<i class="fa-solid fa-chevron-down chev"></i></summary><div class="body"><table class="tbl"><tbody>'+CONSERVATION.map(x=>'<tr><td><b>'+x[0]+'</b></td><td>'+x[1]+'</td></tr>').join('')+'</tbody></table><ul class="clean xs"><li>Téléphone et ordinateur verrouillés et chiffrés; double authentification</li><li>Aucun nom complet ni détail de santé dans le calendrier</li><li>Dossiers papier sous clé, jamais dans l\'auto</li><li>Incident grave : aviser les personnes et le Commissariat à la protection de la vie privée (et la CAI pour une cliente du Québec)</li><li>Cette appli garde les dossiers seulement sur cet appareil : verrouillez-le</li></ul></div></details>';
  h+='<details class="acc"><summary>'+icon('fa-scale-balanced','var(--accent)')+'Code d\'éthique de l\'Académie<i class="fa-solid fa-chevron-down chev"></i></summary><div class="body"><ol class="small" style="margin:0;padding-left:20px;display:flex;flex-direction:column;gap:4px">'+ETHIQUE.map(x=>'<li>'+x+'</li>').join('')+'</ol></div></details>';
  h+='<details class="acc"><summary>'+icon('fa-dove','var(--accent)')+'Deuil périnatal · remise en personne seulement<i class="fa-solid fa-chevron-down chev"></i></summary><div class="body"><ul class="clean small">'+DEUIL.map(x=>'<li>'+x+'</li>').join('')+'</ul></div></details>';
  h+='<div class="card"><span class="eyebrow acc">Sources de référence</span><div class="list">'+Object.values(SRC).map(s=>'<div class="li"><div class="ic">'+icon('fa-book')+'</div><div class="tx"><a href="'+s[1]+'" target="_blank" rel="noopener"><b>'+s[0]+'</b></a><span>'+s[1].replace('https://','')+'</span></div></div>').join('')+'</div></div>';return h}

/* ================== FENÊTRES ================== */
function sheet(title,body){$('#layer').innerHTML='<div class="modal" data-act="closeBg"><div class="sheet" role="dialog" aria-label="'+esc(title)+'"><div class="sheet-h"><h2>'+title+'</h2><button class="icon-btn" data-act="close" aria-label="Fermer" style="font-size:1.2rem">'+icon('fa-xmark')+'</button></div>'+body+'</div></div>'}
function close(){$('#layer').innerHTML='';S.tmp=null}
const W=()=>'<label class="f">Moment<input type="datetime-local" id="m_t" value="'+nowLocal()+'"></label>';
function getT(){const v=$('#m_t')&&$('#m_t').value;return v?new Date(v).getTime():Date.now()}
function addLog(o){o.id=uid();o.t=o.t||Date.now();S.logs.push(o);save();close();render();toast('Ajouté au journal')}
const FORMS={
 humeur:()=>sheet('Mon humeur','<div class="row" style="justify-content:space-between">'+MOODS.map((m,i)=>'<button class="chip" data-act="pickMood" data-v="'+i+'" style="flex-direction:column;border-radius:16px;padding:10px 8px;gap:4px;flex:1;min-width:56px">'+icon(m[0]).replace('<i ','<i style="font-size:1.4rem" ')+'<span style="font-size:.64rem">'+m[1]+'</span></button>').join('')+'</div><label class="f">Un mot sur ma journée<input type="text" id="m_note"></label>'+W()+'<button class="btn" data-act="saveMood">Enregistrer</button>'),
 symptome:()=>sheet('Symptômes','<div class="row">'+SYMPTOMS.map(x=>'<button class="chip" data-act="toggleChip">'+esc(x)+'</button>').join('')+'</div><label class="f">Note<input type="text" id="m_note"></label>'+W()+'<button class="btn" data-act="saveSym">Enregistrer</button>'),
 biberon:()=>sheet('Biberon','<div class="grid2"><label class="f">Quantité (ml)<input type="number" id="m_ml" inputmode="numeric" value="60"></label><label class="f">Lait<select id="m_lait"><option value="maternel">Lait maternel frais</option><option value="congele">Lait maternel congelé</option><option value="preparation">Préparation commerciale</option></select></label></div>'+W()+'<p class="xs muted">Biberon « au rythme du bébé » : bébé assis, biberon horizontal, pauses fréquentes.</p><button class="btn" data-act="saveBib">Enregistrer</button>'),
 tirage:()=>sheet('Tirage de lait','<div class="grid2"><label class="f">Quantité (ml)<input type="number" id="m_ml" inputmode="numeric" value="80"></label><label class="f">Destination<select id="m_dest"><option value="frigo">Frigo</option><option value="congelateur">Congélateur</option><option value="donne">Donné tout de suite</option></select></label></div>'+W()+'<p class="xs muted">Date sur chaque contenant, le plus vieux d\'abord, au fond du frigo.</p><button class="btn" data-act="saveTir">Enregistrer</button>'),
 couche:()=>sheet('Couche','<div class="row"><button class="chip on" data-act="toggleChip" id="c_pipi">'+icon('fa-droplet')+'Pipi</button><button class="chip" data-act="toggleChip" id="c_selle">'+icon('fa-poo')+'Selle</button></div><label class="f">Couleur de la selle<select id="m_col">'+STOOL.map(x=>'<option>'+x+'</option>').join('')+'</select></label>'+W()+'<p class="xs muted">Selles blanches, grises ou avec du sang : appelez votre professionnel.</p><button class="btn" data-act="saveCouche">Enregistrer</button>'),
 sommeil:()=>sheet('Sommeil','<div class="grid2"><label class="f">Début<input type="datetime-local" id="m_t" value="'+nowLocal()+'"></label><label class="f">Durée (minutes)<input type="number" id="m_min" value="60"></label></div><label class="f">Note<input type="text" id="m_note"></label><p class="xs muted">Sur le dos, dans son lit, rien d\'autre dans le lit.</p><button class="btn" data-act="saveSleep">Enregistrer</button>'),
 poids:()=>sheet('Poids de bébé','<label class="f">Poids (grammes)<input type="number" id="m_g" inputmode="numeric" placeholder="ex. 3420"></label>'+W()+'<button class="btn" data-act="savePoids">Enregistrer</button>'),
 soin:()=>sheet('Soins de maman','<p class="xs muted">Saignements, douleur, périnée, cicatrice, seins, sommeil…</p><label class="f">Note<textarea id="m_note"></textarea></label>'+W()+'<button class="btn" data-act="saveSoin">Enregistrer</button>'),
 note:()=>sheet('Note','<label class="f">Note<textarea id="m_note"></textarea></label>'+W()+'<button class="btn" data-act="saveNote">Enregistrer</button>'),
 feed:()=>sheet('Tétée','<p class="xs muted">Démarrez le minuteur, ou entrez une tétée passée.</p><div class="row"><button class="btn" data-act="feedGo" data-v="G">Démarrer sein gauche</button><button class="btn" data-act="feedGo" data-v="D">Démarrer sein droit</button></div><hr><div class="grid2"><label class="f">Sein<select id="m_side"><option value="G">Gauche</option><option value="D">Droit</option><option value="GD">Les deux</option></select></label><label class="f">Durée (minutes)<input type="number" id="m_min" value="15"></label></div>'+W()+'<button class="btn ghost" data-act="saveFeed">Enregistrer une tétée passée</button>')
};
function birthForm(){const n=S.parent.naissance;sheet('Bébé est né','<p class="xs muted">L\'appli bascule en suivi post-partum (jusqu\'au jour 120).</p><div class="grid2"><label class="f">Date<input type="date" id="b_date" value="'+esc(n.date||iso(new Date()))+'"></label><label class="f">Heure<input type="time" id="b_h" value="'+esc(n.heure)+'"></label><label class="f">Prénom de bébé<input type="text" id="b_pre" value="'+esc(n.prenomBebe)+'"></label><label class="f">Lieu<input type="text" id="b_lieu" value="'+esc(n.lieu||S.parent.lieu)+'"></label><label class="f">Poids (g)<input type="number" id="b_p" value="'+esc(n.poids)+'"></label><label class="f">Taille (cm)<input type="number" id="b_t" value="'+esc(n.taille)+'"></label></div><button class="btn" data-act="saveBirth">Enregistrer</button>'+(n.date?'<button class="btn ghost sm" data-act="unBirth">Revenir au suivi de grossesse</button>':''))}
function clientForm(c){c=c||{};S.tmp=JSON.parse(JSON.stringify(c));if(!S.tmp.no)S.tmp.no=new Date().getFullYear()+'-'+pad(S.clients.length+1);
  sheet(c.id?'Modifier le dossier':'Nouvelle famille','<div class="grid2 resp">'+ui.text('tmp.prenom','Prénom de la maman')+ui.text('tmp.nomFamille','Nom de famille')+ui.text('tmp.courriel','Courriel (pour l\'invitation)','email')+ui.text('tmp.partenaire','Partenaire / soutien')+ui.text('tmp.no','No de dossier')+ui.text('tmp.tel','Téléphone','tel')+ui.text('tmp.adresse','Adresse')+ui.text('tmp.dpa','Date prévue (DPA)','date')+ui.text('tmp.ddr','ou dernières règles','date')+ui.text('tmp.lieu','Lieu de naissance prévu')+ui.text('tmp.prof','Professionnel de suivi')+ui.text('tmp.enfants','Enfants à la maison')+ui.text('tmp.allergies','Allergies (huiles, latex…)')+'</div><span class="small"><b>Forfait</b></span>'+ui.pick('tmp.forfait',Object.keys(FORFAITS))+ui.area('tmp.notes','Notes (santé, culture à respecter, ce qu\'ils recherchent)','',70)+(c.id?'':'<label class="check"><input type="checkbox" id="k_inviter" checked><span>Envoyer tout de suite le courriel d\'invitation pour qu\'elle finalise son inscription</span></label>')+'<button class="btn" data-act="saveClient" data-id="'+(c.id||'')+'">Enregistrer</button>')}
function rdvForm(cid,r){const c=S.clients.find(x=>x.id===cid);S.tmp=r?JSON.parse(JSON.stringify(r)):{date:iso(new Date()),type:'',sujets:{},outils:{},alerte:'Non'};const s=cStage(c);if(!r&&s.k==='preg')S.tmp.sem=s.w+' + '+s.d;
  sheet('Fiche de rencontre','<div class="grid2">'+ui.text('tmp.date','Date','date')+ui.text('tmp.duree','Durée')+'</div><label class="f">Type<select data-act="txt" data-p="tmp.type" id="tmp_type"><option value="">Choisir…</option>'+['Appel découverte',...RENCONTRES.map(x=>x[0]),'Rencontre supplémentaire','Visio'].map(t=>'<option '+(S.tmp.type===t?'selected':'')+'>'+t+'</option>').join('')+'</select></label>'+ui.text('tmp.meteo','Comment vont les parents ? (humeur, sommeil, énergie, leurs mots)')+ui.text('tmp.medical','Nouvelles du suivi médical (rapportées par les parents)')+'<p class="grp-t">Sujets abordés</p>'+ui.checks('tmp.sujets',SUJETS)+'<p class="grp-t">Outils remis</p>'+ui.checks('tmp.outils',OUTILS_REMIS)+ui.area('tmp.obs','Mes observations (faits, sans jugement)','',70)+'<span class="small"><b>Signal d\'alerte</b></span>'+ui.pick('tmp.alerte',['Non','Oui'])+ui.text('tmp.orientation','Si oui : lequel et orientation')+ui.text('tmp.afaire','Suivi à faire avant la prochaine rencontre')+ui.text('tmp.prochaine','Prochaine rencontre','date')+'<button class="btn" data-act="rdvSave" data-id="'+cid+'">Enregistrer</button>')}

/* Résumé à partager (parents → doula) */
function makeResume(){const st=stage(),p=S.parent,r={t:Date.now(),n:p.prenom,k:st.k};
  if(st.k==='preg'){r.g=st.g.w+' SA + '+st.g.d+' j · date prévue '+fmtD(st.g.dpa);r.dpa=iso(st.g.dpa)}
  if(st.k==='pp'){const c=last24(['couche']);r.f=last24(['sein','biberon']).length;r.w=c.filter(x=>x.pipi).length;r.s=c.filter(x=>x.selle).length;r.nb=p.naissance.date;r.bebe=p.naissance.prenomBebe;const lf=S.logs.filter(l=>l.type==='sein'||l.type==='biberon').sort((a,b)=>b.t-a.t)[0];if(lf)r.last=lf.t}
  const m=S.logs.filter(l=>l.type==='humeur').sort((a,b)=>b.t-a.t)[0];if(m){r.mood=m.v;r.mn=m.note||''}
  r.moral=Object.values(p.moral||{}).some(Boolean);r.sym=[...new Set(S.logs.filter(l=>l.type==='symptome'&&l.t>Date.now()-3*DAY).flatMap(l=>l.list||[]))];r.peurs=p.peurs;r.plan=Object.keys(p.plan).filter(k=>p.plan[k]);return 'SRN1.'+enc(r)}
